export function ownerF024Reconstruction(components:BuildingComponent[]){const stats:OwnerReconstructionStats={objects:0,vertices:0,triangles:0,originalVertices:0,sourceRetained:true,actualVisualAccepted:false,components:[]};if(!components.some(c=>c.city==='berlin'&&ownerF024Identity(c)))return{components,stats};const ready=F024_IDS.every(i=>components.filter(c=>c.city===i.city&&c.objectId===i.objectId&&c.partId===i.partId).length===1&&components.some(c=>c.city===i.city&&c.objectId===i.objectId&&c.partId===i.partId&&nativePaintSignature(c)===i.signature&&JSON.stringify(c.origin)===JSON.stringify(SOURCE[c.partId].origin)&&JSON.stringify(c.componentGeometry)===JSON.stringify(SOURCE[c.partId].componentGeometry)&&JSON.stringify(c.sourceFeature)===JSON.stringify(SOURCE[c.partId].sourceFeature)&&c.batches.length===SOURCE[c.partId].batches.length&&c.batches.every((b,bi)=>["positions","normals","indices","color"].every(k=>{const a=(b as any)[k],e=SOURCE[c.partId].batches[bi][k];return a?.length===e.length&&Array.from(a as ArrayLike<number>).every((v,j)=>Object.is(v,e[j]));}))));if(!ready){stats.error='F024 requires all11 unchanged real native carriers';return{components,stats};}return{components:components.map(c=>{if(c.city!=='berlin'||!ownerF024Identity(c))return c;const batches=DISPLAY[c.partId].map(b=>({...b,positions:[...b.positions],normals:[...b.normals],indices:[...b.indices],color:[...b.color],frames:[...b.frames],paint:[...b.paint],writeMask:[...b.writeMask]}));const vertices=batches.reduce((s,b)=>s+b.positions.length/3,0),triangles=batches.reduce((s,b)=>s+b.indices.length/3,0);stats.objects++;stats.vertices+=vertices;stats.triangles+=triangles;stats.originalVertices+=c.batches.reduce((s,b)=>s+b.positions.length/3,0);stats.components.push({objectId:c.objectId,partId:c.partId,sourcePartId:c.partId,patchSHA256:F024_RECONSTRUCTION_SHA,vertices,triangles,geometryRole:'owner-authorized-reconstruction'});return{...c,batches,displayEstimates:{...c.displayEstimates,F024Exterior:{sourceRetained:true,patchSHA:F024_RECONSTRUCTION_SHA,originalSourcesAndOldProgramsRetained:true,platformDisplayPhotoApproximate:true,localFacadeFrames:true}}};}),stats};}
export function ownerF024BaseMaterials(components:BuildingComponent[],paint:Float32Array,frames:Float32Array){let offset=0,objects=0,vertices=0;for(const c of components){const match=c.city==='berlin'&&ownerF024Identity(c)&&!!c.displayEstimates?.F024Exterior;if(match)objects++;for(const b of c.batches){const count=b.positions.length/3;if(match){const a=b as Batch;for(let j=0;j<count;j++)if(a.writeMask[j]){paint.set(a.paint.slice(j*4,j*4+4),4*(offset+j));frames.set(a.frames.slice(j*5,j*5+5),5*(offset+j));vertices++;}}offset+=count;}}return{objects,vertices,actualVisualAccepted:false};}
